import hashlib, math

class BloomFilter:
    def __init__(self, n: int, fp_rate: float):
        # Optimal sizing for n items at the target false-positive rate
        self.m = math.ceil(-n * math.log(fp_rate) / math.log(2) ** 2)
        self.k = max(1, round(self.m / n * math.log(2)))
        self.bits = bytearray((self.m + 7) // 8)

    def _positions(self, item: str) -> list[int]:
        d = hashlib.sha256(item.encode()).digest()
        h1 = int.from_bytes(d[:8], "big")
        h2 = int.from_bytes(d[8:16], "big") | 1
        # Double hashing: k positions from two hashes
        return [(h1 + i * h2) % self.m for i in range(self.k)]

    def add(self, item: str) -> None:
        for p in self._positions(item):
            self.bits[p // 8] |= 1 << (p % 8)

    def might_contain(self, item: str) -> bool:
        # Any 0 bit: definitely absent. All 1s: probably present.
        return all(self.bits[p // 8] >> (p % 8) & 1 for p in self._positions(item))

seen = BloomFilter(n=1_000_000, fp_rate=0.01)  # ~1.2 MB, k = 7
if not seen.might_contain(url):
    seen.add(url)
    crawl(url)  # ~1% of new URLs are wrongly skipped
